/// Returns the minimum number of inspectors needed to cover `n` items
/// when each inspector covers a contiguous block of length `2*d + 1`.
///
/// This is: ceil(n / (2*d + 1)) = (n + (2*d + 1) - 1) / (2*d + 1)
pub fn min_inspectors(n: i8, d: i8) -> i8 {
    // Use a wider type for intermediate arithmetic to avoid overflow,
    // even though constraints are small.
    let n = n as i32;
    let d = d as i32;

    let block = 2 * d + 1; // maximum items one inspector can cover
    let needed = (n + block - 1) / block; // integer ceil division

    needed as i8
}

